	{
		17003,
		"天元·王者圣龙",
		"",
		"王者圣龙举止优雅贵气，是龙族中的贵族。他拥有数之不尽的金银财宝，却并不在乎这些身外之物。比起把宝石堆放在大殿作为装饰，更愿意奉献出来帮助弱者。他的理想是以圣光为名，除尽世间极恶，每次出现都会让黑暗和邪恶瞬间消失。",
		"财宝？如有需要尽可取去。",
