		"暗祭·达克诺斯",
		"",
		"达克诺斯为神域领神之一，也是圣教的创始人，被信徒们奉为圣主。他永远保持圣洁高雅的外表，风度翩翩的礼仪，然而这一切都只是他的伪装。他作为欺诈天才，同时也是黑魔法分支“黑咒语”的创造者，极其善于以谎言掌控人心。那本欺诈之书“达克诺斯之眼”便是他的作品，是他脑后的第三只眼所化。",
