		"空有一身勇武、满腔热血……有些时候并不见得是一件好事。再为锋利尖锐的剑也有顿挫残破的那一天，对于圣龙来说即是神判日的审判之时。面对强者铺天盖地般的高压还能挺直身板固然值得钦佩，但当颓势渐起、败局已定时，存活千百年来的圣龙第一次感受到了来自内心的犹疑，虽然坚定的精神防线轻易被摧毁，但当祂回首看向身后所守护之物时，还是颤抖着提剑应战，目光如炬，慷慨赴死。而往往命运之于神明而言，并不意味运势好坏多寡，有些时候只是恰巧的刚刚好。这份不破不立的意志与决心，响彻云霄，神曜苍穹。",
