		"不朽枯木·永恒圣龙",
		"",
		"维达好奇心旺盛，平时会观察记录万物的一言一行：从萌芽成长到开花结果，发展规律脉络清晰，宇宙自有它的运行逻辑，旁人不可干预。但祖神战争打破了维达一直以来的认知，从不表态的祂被迫下场站队，于战争中表现堪忧。在一番浑水摸鱼后，维达迫于内疚折下翅膀上一根断枝，帮助创世龙创造精灵大陆的根基脉络，并亲自培育了精灵大陆的世界树。树苗开花散叶，精灵大陆的一草一木、山川河流皆有维达的一份力量。",
