		"神曜永恒·阿瑞斯",
		"",
		"经过维达教诲，阿瑞斯明晰了生命终途的奥义所在——四季有序，万物有时，从稚嫩的幼苗成长为参天大树，再落得一地枯黄，轮回对于生命而言是必定要经历的一环。而在这一生中：生命的本质多维而纷杂，众生百相各露不一，任何人都不能随意侵犯他人生命价值，对于身怀机械之心的阿瑞斯来说，为了守护生命的美好而战便是其存在的意义。",
